UPDATE standing_tables SET config = json_remove(config, '$.snapshot', '$.note') WHERE legacy_id IS NOT NULL AND id IN (SELECT src.table_id FROM standing_table_sources src JOIN matches m ON m.stage_id = src.stage_id AND m.status = 'finished');
